/**
 * SOCIAL_MEDIA q10 in the default (auto) mode on the theme data, with the theme benchmark's planning configuration. Its
 * written-order region contains a dependent candidate whose right-side work is legitimately unknown once the bounded
 * search stops inside a nested contextual costing. Cascades must keep that candidate unpriced and still install its own
 * plan; it must never fall back to the pipeline plan because an unknown price reached the reopen arithmetic.
 */
class LmdbSocialQ10AutoPlanningIT {
	private static final String MODE = "rdf4j.optimizer.lmdb.cascades.mode";
	private static final int QUERY_SECONDS = 60;

	@TempDir
	Path temporary;

	@Test
	@Timeout(600)
	void q10AutoPlansWithCascadesAndKeepsTheUnknownCandidateUnpriced() throws Exception {
		Map<String, String> previous = new HashMap<>();
		SailRepository repository = null;
		try {
			setProperty(previous, MODE, "auto");
			Path data = temporary.resolve("store");
			Files.createDirectory(data);
			LmdbStoreConfig loading = config();
			loading.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
			loading.setIterationCacheSyncThreshold(0);
			repository = new SailRepository(new LmdbStore(data.toFile(), loading));
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				ThemeDataSetGenerator.generate(Theme.SOCIAL_MEDIA, new RDFInserter(connection));
				connection.commit();
			}
			repository.shutDown();
			repository = null;

			LmdbStore store = new LmdbStore(data.toFile(), config());
			repository = new SailRepository(store);
			repository.init();
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			assertTrue(store.awaitDirectAdjacencyReady(600, TimeUnit.SECONDS), "direct adjacency must be ready");
			assertTrue(store.awaitValueOverlayReady(600, TimeUnit.SECONDS), "value overlay must be ready");
			LmdbTestUtil.awaitBackgroundMaintenance(store, 600, TimeUnit.SECONDS);
			var sailStore = store.getSailStore();
			try (var branch = sailStore.getExplicitSailSource().fork();
					var dataset = branch.dataset(store.getDefaultIsolationLevel())) {
				SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(sailStore.getValueFactory(),
						dataset);
				EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, source, sailStore.getEvaluationStatistics());
				TupleExpr input = parse(ThemeQueryCatalog.queryFor(Theme.SOCIAL_MEDIA, 10));
				TupleExpr selected = LmdbBenchmarkQueryPlan.withCascadesOptimizationTimeout(QUERY_SECONDS,
						() -> strategy.optimize(input, sailStore.getEvaluationStatistics(),
								EmptyBindingSet.getInstance()));

				QueryModelNode root = invocationRoot(selected);
				assertNotNull(root, "the optimized plan must carry the Cascades invocation outcome");
				assertNull(root.getStringMetricPlanned("optimizer.cascadesFallback"),
						() -> "Cascades fell back to the pipeline plan: "
								+ root.getStringMetricPlanned("optimizer.cascadesFallbackReason"));
				assertEquals("true", root.getStringMetricPlanned("optimizer.cascadesApplied"));
				assertEquals("UNAVAILABLE", root.getStringMetricPlanned("optimizer.cascadesPriceAvailability"),
						"the candidate with unknown right-side work must stay unpriced");
				assertEquals("UNAVAILABLE_COST",
						root.getStringMetricPlanned("optimizer.cascadesCostComparisonCompleteness"));
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
			for (var entry : previous.entrySet()) {
				if (entry.getValue() == null) {
					System.clearProperty(entry.getKey());
				} else {
					System.setProperty(entry.getKey(), entry.getValue());
				}
			}
		}
	}

	/** The theme planning benchmark's store configuration (its default leaves the sketch estimator disabled). */
	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc,posc");
		config.setForceSync(false);
		config.setValueDBSize(1_073_741_824L);
		config.setTripleDBSize(config.getValueDBSize());
		config.setSketchEstimatorSubjectBucketCount(4096);
		config.setSketchEstimatorPredicateBucketCount(64);
		config.setSketchEstimatorObjectBucketCount(4096);
		config.setSketchEstimatorContextBucketCount(16);
		config.setSketchEstimatorContextPairSketchesEnabled(false);
		config.setNativeEvaluationEnabled(true);
		config.setDirectAdjacencyEnabled(config.getDirectAdjacencyMode() != DirectAdjacencyMode.DISABLED);
		config.setValueOverlayEnabled(true);
		config.setSketchEstimatorEnabled(false);
		config.setSketchEstimatorEvidenceMode("snapshot-only");
		config.setOptimizerSamplingMaxMillis(30_000L);
		return config;
	}

	private static TupleExpr parse(String query) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		return expression instanceof QueryRoot ? expression : new QueryRoot(expression);
	}

	private static QueryModelNode invocationRoot(TupleExpr plan) {
		QueryModelNode[] found = { null };
		plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (found[0] == null && (node.getStringMetricPlanned("optimizer.cascadesApplied") != null
						|| node.getStringMetricPlanned("optimizer.cascadesFallback") != null)) {
					found[0] = node;
					return;
				}
				super.meetNode(node);
			}
		});
		return found[0];
	}

	private static void setProperty(Map<String, String> previous, String key, String value) {
		previous.putIfAbsent(key, System.getProperty(key));
		System.setProperty(key, value);
	}
}
